// Turn n8n's error payload into something a human can act on without opening n8n.
//
// This exists because there was NO failure notification of any kind on any VIO workflow. Three
// things broke during the first live enrolment — an inactive sub-workflow, an authorizer refusal,
// and an enrolment that silently no-opped — and every one was found by reading `docker logs`.
// The operator had no way to know. A pipeline you cannot see failing is one you have to babysit.

// ---------------------------------------------------------------------------
// RATE LIMIT. Added 2026-09-05 after this workflow posted 1,153 messages to Slack in one hour.
//
// On 2026-09-04 the scheduler fired VIO-inbox-mapper ~2,500 times in an hour (85x its cadence),
// the Sheets quota ran out, and every one of those failures came here and went straight to the
// channel. An alert channel that can receive a thousand identical messages is one people mute,
// and a muted channel is exactly the "no failure notification of any kind" this workflow was
// built to end. Two rules, kept in workflow static data so they survive between executions:
//
//   1. DEDUPE   the same workflow + node + reason is posted at most once per DEDUPE_WINDOW.
//   2. STORM    more than STORM_N alerts of ANY kind inside STORM_WINDOW posts ONE storm notice
//               and then goes quiet for STORM_QUIET, counting what it swallowed.
//
// When either window lifts, the next post carries "N suppressed since HH:MM" so nothing is lost
// silently — the operator sees the count, not the flood. Refusals (guards) are counted but never
// trigger the storm rule on their own; a storm is about volume of FAILURES.
const DEDUPE_WINDOW = 10 * 60 * 1000;
const STORM_WINDOW  = 10 * 60 * 1000;
const STORM_N       = 15;
const STORM_QUIET   = 30 * 60 * 1000;

const st = $getWorkflowStaticData('global');
st.seen = st.seen || {};            // signature -> last posted ms
st.win  = st.win  || { start: 0, n: 0 };
st.quietUntil = st.quietUntil || 0;
st.suppressed = st.suppressed || 0;
st.suppressedSince = st.suppressedSince || 0;
const now = Date.now();
const hhmm = (ms) => new Date(ms).toISOString().slice(11, 16) + ' UTC';

const e = $input.first().json || {};
const wf = e.workflow || {};
const ex = e.execution || {};
const err = ex.error || e.error || {};

const clip = (v, n) => String(v === undefined || v === null ? '' : v)
  .replace(/[\u0000-\u001f\u007f]+/g, ' ').trim().slice(0, n);

const name = clip(wf.name, 80) || '(unnamed workflow)';
const node = clip(ex.lastNodeExecuted, 80) || '(unknown node)';
// n8n splits a Code-node throw: `message` can be a trailing fragment ("oryoniq, visioneerit
// [line 36]") while the real text sits in `description`. Reading only `message` produced an alert
// that named a symptom nobody could act on. Prefer whichever actually contains the REFUSED text,
// then fall back to the longer of the two.
const cand = [err.description, err.message, err.cause && err.cause.message]
  .filter((x) => typeof x === 'string' && x.trim());
const withRefused = cand.find((x) => /REFUSED/.test(x));
let message = clip(withRefused || cand.sort((a, b) => b.length - a.length)[0] || '', 600) || '(no message)';

// n8n prefixes thrown Code-node errors; the REFUSED text is the part that matters, so lead with it.
const refused = message.match(/REFUSED:[^]*/);
const headline = refused ? clip(refused[0], 400) : message;

// A refusal is a GATE DOING ITS JOB, not an outage. Saying so stops the on-call reflex of
// "something is broken" when the correct read is "something was correctly stopped".
const isRefusal = /REFUSED/.test(message);

const base = ($env.N8N_EDITOR_BASE_URL || '').replace(/\/+$/, '');
const link = (base && ex.id) ? `${base}/workflow/${clip(wf.id, 40)}/executions/${clip(ex.id, 20)}` : '';

const sig = `${name}|${node}|${headline.slice(0, 100)}`;

// ---- storm bookkeeping (failures only) --------------------------------------------------------
if (!isRefusal) {
  if (now - st.win.start > STORM_WINDOW) st.win = { start: now, n: 0 };
  st.win.n += 1;
}

// ---- quiet period after a storm ---------------------------------------------------------------
if (now < st.quietUntil) {
  st.suppressed += 1;
  return [];                                                   // nothing posts
}

// ---- storm trips: post ONE notice, then go quiet ---------------------------------------------
if (!isRefusal && st.win.n > STORM_N) {
  st.quietUntil = now + STORM_QUIET;
  st.suppressedSince = now;
  const swallowed = st.suppressed; st.suppressed = 0;
  st.win = { start: now, n: 0 };
  return [{ json: {
    subject: `STORM: ${name}`,
    text:
      `*:cloud_with_lightning: Alert storm* — ${name}\n` +
      `More than ${STORM_N} failures in ${STORM_WINDOW / 60000} minutes, latest at *${node}*:\n` +
      `> ${headline.slice(0, 200)}\n` +
      `Suppressing further alerts until ${hhmm(st.quietUntil)}. ` +
      (swallowed ? `${swallowed} already swallowed. ` : '') +
      `Run \`diagnose.py\` — a scheduler firing far above cadence is a defect regardless of the message.`,
    is_refusal: false, is_storm: true, workflow_name: name, node_name: node,
  } }];
}

// ---- dedupe: same signature inside the window ------------------------------------------------
const last = st.seen[sig] || 0;
if (now - last < DEDUPE_WINDOW) {
  st.suppressed += 1;
  if (!st.suppressedSince) st.suppressedSince = now;
  return [];
}
st.seen[sig] = now;
// keep the map from growing forever
for (const k of Object.keys(st.seen)) if (now - st.seen[k] > 24 * 3600 * 1000) delete st.seen[k];

const swallowed = st.suppressed;
const since = st.suppressedSince;
st.suppressed = 0; st.suppressedSince = 0;
const suppressedLine = swallowed ? `\n_${swallowed} similar alert(s) suppressed since ${hhmm(since)}._` : '';

return [{ json: {
  subject: `${isRefusal ? 'Refused' : 'FAILED'}: ${name}`,
  text:
    `*${isRefusal ? ':no_entry: Refused' : ':rotating_light: Workflow failed'}* — ${name}\n` +
    `*Node:* ${node}\n` +
    `*Reason:* ${headline}\n` +
    (ex.id ? `*Execution:* ${clip(ex.id, 20)}\n` : '') +
    (link ? `${link}\n` : '') +
    (isRefusal
      ? '\nThis is a guard refusing, not an outage — nothing was spent and nobody was contacted.'
      : '\nNothing downstream of this node ran.') + suppressedLine,
  is_refusal: isRefusal,
  workflow_name: name,
  node_name: node,
} }];
